-- ============================================================
-- DBD Hub - Perks (3 unicas por killer y por survivor)
-- Fuente: Dead by Daylight / dbd.source.gs (patch 10.2.2)
-- Ejecutar con:
--   psql -h localhost -p 5432 -U dbdhub_user -d DBDHubDB -f Data/Seed/dbd_perks_seed.sql
-- ============================================================

SET client_encoding = 'UTF8';
BEGIN;

-- Limpia perks previas (incluidas las de OWASP ZAP)
DELETE FROM public."Perks";

-- Survivors presentes en el roster actual y ausentes del seed inicial
INSERT INTO public."Survivors" ("Nombre","Historia","Dificultad","ImagenUrl","Activo","FechaCreacion")
SELECT v.nombre, v.historia, v.dificultad, NULL, true, now()
FROM (VALUES
    ('Jonah Vasquez','Criptografo bilingue que descifra los mensajes ocultos del reino.','Medio'),
    ('Shane Wiigwaas','Superviviente resistente que sobrevive gracias a su conocimiento del terreno.','Medio')
) AS v(nombre,historia,dificultad)
WHERE NOT EXISTS (SELECT 1 FROM public."Survivors" s WHERE s."Nombre" = v.nombre);

-- Perks de KILLERS
INSERT INTO public."Perks"
    ("Nombre","Descripcion","Nivel","TipoPersonaje","KillerId","SurvivorId","Activo","FechaCreacion","ImagenUrl")
SELECT p.nombre, p.descripcion, 3, 'Killer', k."Id", NULL, true, now(), p.imagen
FROM (VALUES
    ('Agitation','While carrying a Survivor: - You gain 14/16/18% Haste. - Your Terror Radius is 12 m larger.','The Trapper','https://cdn.source.gs/dead-by-daylight/img/agitation-10c07e.webp'),
    ('Brutal Strength','You basic-break Pallets and Breakable Walls, and damage Generators 10/15/20% faster.','The Trapper','https://cdn.source.gs/dead-by-daylight/img/brutal-strength-882d20.webp'),
    ('Unnerving Presence','Survivors within your Terror Radius get 10% more basic Skill Checks. The good zone of basic Skill Checks is 40/50/60% smaller.','The Trapper','https://cdn.source.gs/dead-by-daylight/img/unnerving-presence-f3c574.webp'),
    ('Bloodhound','Pools of Blood are brighter and last 2/3/4 s longer.','The Wraith','https://cdn.source.gs/dead-by-daylight/img/bloodhound-50bc24.webp'),
    ('Predator','When you stop chasing a Survivor, you see their Aura for 4 s. Cooldown: 60/50/40 s.','The Wraith','https://cdn.source.gs/dead-by-daylight/img/predator-9a7078.webp'),
    ('Shadowborn','Whenever you are blinded, gain 6/8/10% Haste for 10 s.','The Wraith','https://cdn.source.gs/dead-by-daylight/img/shadowborn-6e8e85.webp'),
    ('Enduring','While not carrying a Survivor, Pallet-stuns are 40/45/50% shorter.','The Hillbilly','https://cdn.source.gs/dead-by-daylight/img/enduring-0939f8.webp'),
    ('Lightborn','Whenever a Survivor attempts to blind you, you see their Aura for 6/8/10 s. You cannot be blinded.','The Hillbilly','https://cdn.source.gs/dead-by-daylight/img/lightborn-b9b9a1.webp'),
    ('Tinkerer','The first time each Generator has 70% progress: - You gain Undetectable for 12/14/16 s. - You are alerted.','The Hillbilly','https://cdn.source.gs/dead-by-daylight/img/tinkerer-41a468.webp'),
    ('A Nurse''s Calling','Within 28/30/32 m of Survivors who are healing or being healed, you see their Auras.','The Nurse','https://cdn.source.gs/dead-by-daylight/img/nursecalling-676ebe.webp'),
    ('Stridor','Survivors'' breathing noises are 15/20/25% louder and their Grunts of Pain are 30/40/50% louder.','The Nurse','https://cdn.source.gs/dead-by-daylight/img/stridor-b3a0cf.webp'),
    ('Thanatophobia','For each injured, downed, or hooked Survivor, all Survivors: - Cleanse Totems 1/1.5/2% slower. - Repair 1/1.5/2% slower. - Sabotage Hooks 1/1.5/2% slower. While 4 Survivors are either injured, downed or hooked, all above actions are additionally 12% slower.','The Nurse','https://cdn.source.gs/dead-by-daylight/img/thanatophobia-bcf628.webp'),
    ('Hex: Devour Hope','When the trial starts, a Dull Totem ignites. Whenever a Survivor is unhooked while you are at least 24 m away, earn 1 Token, up to 5: - 2 Tokens | 10 s after hooking a Survivor, gain 3/4/5% Haste for 10 s. - 3 Tokens | Survivors gain Exposed. - 5 Tokens | You can Kill downed Survivors.','The Hag','https://cdn.source.gs/dead-by-daylight/img/hex-devour-hope-2ff4d6.webp'),
    ('Hex: Ruin','When the trial starts, a Dull Totem ignites. While a Generator is not being repaired, it regresses at 100/125/150% speed.','The Hag','https://cdn.source.gs/dead-by-daylight/img/hex-ruin-2cde4c.webp'),
    ('Hex: The Third Seal','When the trial starts, a Dull Totem ignites. Whenever you damage a Survivor with a basic or special-attack, they gain Blindness. This applies for up to 2/3/4 Survivors.','The Hag','https://cdn.source.gs/dead-by-daylight/img/hex-the-third-seal-4a043b.webp'),
    ('Dying Light','Whenever you hook a Survivor that is not the Obsession, earn 1 token. While the Obsession is alive, for each Token: - Other Survivors heal 2/2.5/3% slower. - Other Survivors repair 2/2.5/3% slower. - Other Survivors sabotage Hooks 2/2.5/3% slower. The Obsession: - Heals other Survivors 33% faster. - Unhooks other Survivors 33% faster.','The Shape','https://cdn.source.gs/dead-by-daylight/img/dying-light-274938.webp'),
    ('Play With Your Food','Whenever you stop chasing the Obsession, you earn 1 Token, up to 3. Cooldown: 10 s. For each Token, gain 3/4/5% Haste. Whenever you attack, lose 1 Token.','The Shape','https://cdn.source.gs/dead-by-daylight/img/play-with-your-food-c34553.webp'),
    ('Save the best for last','Whenever you damage a Survivor who is not the Obsession with a basic-attack, you earn 1 Token, up to 6/7/8. For each Token, your successful basic-attack cooldown is 5% shorter. Whenever the Obsession takes damage, lose 2 Tokens. While the Obsession is dead, you cannot earn Tokens.','The Shape','https://cdn.source.gs/dead-by-daylight/img/save-the-best-for-last-4fe3f1.webp'),
    ('Monitor & Abuse','While chasing a Survivor, your Terror Radius is 5/10/15% bigger. While not chasing a Survivor, your Terror Radius is 15/20/25% smaller.','The Doctor','https://cdn.source.gs/dead-by-daylight/img/monitorandabuse-0c4b56.webp'),
    ('Overcharge','Whenever you damage a Generator: - Its regression speed will go from 85% to 130% over the next 30 s. - The next Survivor who starts repairing it gets a special Skill Check. If they miss it, they lose 2/3/4% more progress.','The Doctor','https://cdn.source.gs/dead-by-daylight/img/generatorovercharge-5a103c.webp'),
    ('Overwhelming Presence','Whenever a Survivor uses an item within 32 m of you, they gain Exhausted for 15 s. Whenever a Survivor within 32 m of you gains Exhausted, you see the closest Exhausted Survivor''s Aura for 2/3/4 s. Cooldown: 25 s.','The Doctor','https://cdn.source.gs/dead-by-daylight/img/overwhelmingpresence-701e97.webp'),
    ('Beast of Prey','Whenever you gain Bloodlust, gain Undetectable for 30/35/40 s.','The Huntress','https://cdn.source.gs/dead-by-daylight/img/beastofprey-ec024a.webp'),
    ('Hex: Huntress Lullaby','When the trial starts, a Dull Totem ignites. Whenever you hook a Survivor, earn 1 Token. For each Token, Basic Skill Check warnings appear later and good success zones are smaller. While you have 5 Tokens, Basic Skill Check warnings don''t appear. Whenever a Survivor misses a basic Skill Check, they lose 2/4/6% more progress.','The Huntress','https://cdn.source.gs/dead-by-daylight/img/hex-huntresslullaby-fe5fd9.webp'),
    ('Territorial Imperative','Whenever a Survivor enters the Basement while you are 24 m away from it, you see their Aura for 4/5/6 s. Cooldown: 45 s.','The Huntress','https://cdn.source.gs/dead-by-daylight/img/territorialimperative-3f56be.webp'),
    ('Barbecue & Chili','Whenever you hook a Survivor, for 5 s, you see the Auras of all Survivors who are at least 60/50/40 m away from the hooked Survivor.','The Cannibal','https://cdn.source.gs/dead-by-daylight/img/bbqandchilli-bc88b3.webp'),
    ('Franklin''s Demise','Whenever you damage a Survivor with a basic-attack, they drop their item. Within 32/48/64 m, you see the Auras of dropped items.','The Cannibal','https://cdn.source.gs/dead-by-daylight/img/franklinsloss-9f5cbe.webp'),
    ('Knock Out','Whenever a Survivor drops a Pallet, for the next 6 s, if they move 10 m away from it, they gain 20% Hindered for 2/3/4 s. This ends early if the Pallet is broken.','The Cannibal','https://cdn.source.gs/dead-by-daylight/img/inthedark-667f5e.webp'),
    ('Blood Warden','When an Exit Gate is opened, once per trial, when you hook a Survivor, both Exits are blocked for 40/50/60 s. You see the Auras of Survivors within Exit Thresholds.','The Nightmare','https://cdn.source.gs/dead-by-daylight/img/bloodwarden-ea1bbd.webp'),
    ('Fire Up','Whenever a Generator is completed, earn 1 Token, up to 5. For each Token: - You basic-break Pallets and Breakable Walls 6/7/8% faster. - You damage Generators 6/7/8% faster. - You pick-up and drop Survivors 6/7/8% faster. - You basic-vault Windows 6/7/8% faster.','The Nightmare','https://cdn.source.gs/dead-by-daylight/img/fireup-dfb208.webp'),
    ('Remember Me','Whenever the Obsession takes damage, you earn 1 Token, up to 3/4/5. For each Token, Survivors who are not the Obsession open Exit Gates 30% slower.','The Nightmare','https://cdn.source.gs/dead-by-daylight/img/rememberme-05c78e.webp'),
    ('Make your Choice','Whenever a Survivor unhooks another or themselves while you are at least 32 m away: - They scream. - They gain Exposed for 40/50/60 s. Cooldown: 40/50/60 s.','The Pig','https://cdn.source.gs/dead-by-daylight/img/makeyourchoice-325f36.webp'),
    ('Scourge Hook: Hangman''s Trick','When the trial starts, 4 random Hooks become Scourge Hooks. While carrying a Survivor, you see the Auras of Survivors within 12/14/16 m of Scourge Hooks. Whenever a Survivor starts sabotaging a Hook, you are alerted.','The Pig','https://cdn.source.gs/dead-by-daylight/img/hangmanstrick-5e617d.webp'),
    ('Surveillance','You see the Auras of regressing Generators. Whenever a Generator stops regressing, you see its Aura for 8/12/16 s. Generator repair noises can be heard from 8 m farther away.','The Pig','https://cdn.source.gs/dead-by-daylight/img/surveillance-4de61c.webp'),
    ('Bamboozle','Whenever you vault a Window, it is blocked for Survivors for 8/12/16 s. You basic-vault Windows 5/10/15% faster. Only 1 Window can be blocked at a time.','The Clown','https://cdn.source.gs/dead-by-daylight/img/bamboozle-790235.webp'),
    ('Coulrophobia','Survivors within your Terror Radius: - Heal 20/25/30% slower. - While healing, basic Skill Checks spin 50% faster.','The Clown','https://cdn.source.gs/dead-by-daylight/img/coulrophobia-f6a645.webp'),
    ('Pop Goes the Weasel','Whenever you hook a Survivor, for the next 35/40/45 s, when you damage a Generator, it explodes and loses 15% more progress.','The Clown','https://cdn.source.gs/dead-by-daylight/img/pop-goes-the-weasel-b6cbe5.webp'),
    ('Hex: Haunted Ground','When the trial starts, 2 Dull Totems ignite. When either of those Hex Totems is blessed or cleansed: - All Survivors gain Exposed for 40/50/60 s. - The other Totem is extinguished.','The Spirit','https://cdn.source.gs/dead-by-daylight/img/hex-hauntedground-54687b.webp'),
    ('Rancor','Whenever a Generator is completed: - You are alerted to the position of all Survivors for 3 s. - The Obsession sees your Aura for 5/4/3 s. When all Generators are completed: - The Obsession gains Exposed. - You can Kill the Obsession.','The Spirit','https://cdn.source.gs/dead-by-daylight/img/rancor-195aee.webp'),
    ('Spirit Fury','After you break 4/3/2 Pallets, when you are Pallet-stunned, the Pallet is destroyed.','The Spirit','https://cdn.source.gs/dead-by-daylight/img/spiritfury-4e21e9.webp'),
    ('Discordance','Within 64/96/128 m of you, whenever a Generator is being repaired by at least 2 Survivors, you are alerted. While that Generator is being repaired by at least 2 Survivors, you see its Aura. When it is no longer being repaired by at least 2 Survivors, this ends after 4 s.','The Legion','https://cdn.source.gs/dead-by-daylight/img/discordance-f93ac9.webp'),
    ('Iron Maiden','Whenever a Survivor exits a Locker: - They gain Exposed for 30 s. - They scream, then you are alerted to their location for 4 s. You open Lockers 30/40/50% faster.','The Legion','https://cdn.source.gs/dead-by-daylight/img/ironmaiden-34b2cb.webp'),
    ('Mad Grit','While carrying a Survivor: - Whenever you miss a basic-attack, your cooldown is 100% shorter. - Whenever you damage a Survivor with a basic attack, the carried Survivor gains no wiggle progress for 2/3/4 s.','The Legion','https://cdn.source.gs/dead-by-daylight/img/madgrit-df116e.webp'),
    ('Corrupt Intervention','When the trial starts, the 3 farthest Generators from you are blocked for 80/100/120 s, or until you down a Survivor.','The Plague','https://cdn.source.gs/dead-by-daylight/img/corruptintervention-332607.webp'),
    ('Dark Devotion','Whenever the Obsession takes damage, for 35/40/45 s: - Your Terror Radius is set to 40 m. - The Obsession has your Terror Radius. - You gain Undetectable.','The Plague','https://cdn.source.gs/dead-by-daylight/img/darkdevotion-c35567.webp'),
    ('Infectious Fright','Whenever a Survivor is downed, Survivors within your Terror Radius scream and you are alerted for 4/5/6 s.','The Plague','https://cdn.source.gs/dead-by-daylight/img/infectiousfright-fdae4f.webp'),
    ('Furtive Chase','Whenever you hook the Obsession: - You gain 10% Haste for 14/16/18 s. - You gain Undetectable for 14/16/18 s. Whenever the Obsession is unhooked, the Survivor who unhooked them becomes the Obsession.','The Ghost Face','https://cdn.source.gs/dead-by-daylight/img/furtivechase-cd92b9.webp'),
    ('I''m All Ears','Whenever a Survivor fast-enters or fast-exits a Locker, or medium or fast-vaults within 48 m of you, you see their Aura for 8 s. Cooldown: 60/45/30 s.','The Ghost Face','https://cdn.source.gs/dead-by-daylight/img/imallears-9155c0.webp'),
    ('Thrilling Tremors','Whenever you pick-up a Survivor, all Generators not being repaired are blocked for 16 s. Cooldown: 40/35/30 s.','The Ghost Face','https://cdn.source.gs/dead-by-daylight/img/thrillingtremors-09a847.webp'),
    ('Cruel Limits','Whenever a Generator is completed: - You see the Auras of all Windows for 20/25/30 s. - All Windows are blocked for Survivors for 20/25/30 s.','The Demogorgon','https://cdn.source.gs/dead-by-daylight/img/cruelconfinement-86b27d.webp'),
    ('Mindbreaker','While Survivors are repairing a Generator: - They gain Blindness. - They gain Exhausted. When they stop repairing a Generator, this ends after 3/4/5 s.','The Demogorgon','https://cdn.source.gs/dead-by-daylight/img/mindbreaker-732ea3.webp'),
    ('Surge','Whenever you down a Survivor with a basic-attack, Generators within 32 m: - Explode, lose 6/7/8% progress and start regressing. - Survivor repairing them scream.','The Demogorgon','https://cdn.source.gs/dead-by-daylight/img/surge-0b3140.webp'),
    ('Blood Echo','Whenever you hook a Survivor, for 20/25/30 s, all injured Survivors: - Gain Exhausted. - Gain Hemorrhage.','The Oni','https://cdn.source.gs/dead-by-daylight/img/bloodecho-73f19b.webp'),
    ('Nemesis','Whenever a Survivor blinds you, Locker-stuns or Pallet-stuns you, they become the Obsession. Whenever a Survivor becomes the Obsession: - They gain Oblivious for 40/50/60 s. - You see their Aura for 8 s.','The Oni','https://cdn.source.gs/dead-by-daylight/img/nemesis-8c887f.webp'),
    ('Zanshin Tactics','Within 32 m, you see the Auras of Pallets and windows. Whenever a Survivor drops a Pallet, you see their Aura for 3/4/5 s.','The Oni','https://cdn.source.gs/dead-by-daylight/img/zanshintactics-2fcae1.webp'),
    ('Dead Man’s Switch','Whenever you hook a Survivor, the next time any Survivor stops repairing a Generator for more than 2 s, it is blocked for 30/35/40 s. Cooldown: 30/35/40 s.','The Deathslinger','https://cdn.source.gs/dead-by-daylight/img/deadmansswitch-7c1b9c.webp'),
    ('Gearhead','Whenever a Survivor takes damage, for the next 30 s, whenever a Survivor repairing a Generator hits a good basic Skill Check, you see their Aura for 6/7/8 s.','The Deathslinger','https://cdn.source.gs/dead-by-daylight/img/gearhead-2de728.webp'),
    ('Hex: Retribution','When the trial starts, a Dull Totem ignites. Whenever a Survivor starts blessing or cleansing a Totem, they gain Oblivious for 40/50/60 s. Whenever a Hex Totem is blessed or cleansed, you see the Auras of all Survivors for 20 s.','The Deathslinger','https://cdn.source.gs/dead-by-daylight/img/hexretribution-059ce2.webp'),
    ('Deathbound','Whenever a Survivor finishes healing another, the healer screams. Then, until the healer takes damage, while they are at least 12/8/4 m away from the healed Survivor: - The healer gains Oblivious. - The healer sees the healed Survivor''s Aura. This can only apply to one Survivor at a time.','The Executioner','https://cdn.source.gs/dead-by-daylight/img/deathbound-1a4dfb.webp'),
    ('Forced Penance','Whenever a Survivor takes a protection hit, they gain Broken for 60/70/80 s.','The Executioner','https://cdn.source.gs/dead-by-daylight/img/forcedpenance-68986f.webp'),
    ('Trail of Torment','You guide your victims along a path of pain and punishment. After damaging a generator, you become Undetectable until the generator stops regressing. During this time, the generator’s yellow aura is revealed to Survivors. This effect can only trigger once every 60/45/30 seconds. Undetectable hides the Killer''s aura, Terror Radius, and Red Stain.','The Executioner','https://cdn.source.gs/dead-by-daylight/img/trailoftorment-d33916.webp'),
    ('Dragon’s Grip','Whenever you damage a Generator, for the next 30 s, the first Survivor that repairs that Generator: - They scream, then you are alerted to their position for 4 s. - They gain Exposed for 60 s. Cooldown: 60/45/30 s.','The Blight','https://cdn.source.gs/dead-by-daylight/img/dragonsgrip-45de26.webp'),
    ('Hex: Blood Favor','When the trial starts, a Dull Totem ignites. Whenever a healthy Survivor becomes injured by your basic-attack, Upright Pallets within 32 m of them are blocked for 13/14/15 s.','The Blight','https://cdn.source.gs/dead-by-daylight/img/hexbloodfavor-71fdad.webp'),
    ('Hex: Undying','When the trial starts, a Dull Totem ignites. When another Hex Totem is blessed or cleansed, it replaces this one and keeps any Tokens it had. You see the Auras of Survivors within 2/3/4 m of Dull Totems.','The Blight','https://cdn.source.gs/dead-by-daylight/img/hexundying-a9170b.webp'),
    ('Coup de Grâce','Whenever a Generator is completed, you earn 2 Tokens, up to 5. Whenever you lunge-attack, spend 1 Token to make it 70/75/80% longer.','The Twins','https://cdn.source.gs/dead-by-daylight/img/k22p03-8c2419.webp'),
    ('Hoarder','When the trial starts, 2 more Chests appear. Whenever a Survivor picks-up an Item or starts unlocking a Chest within 32/48/64 m of you, you are alerted.','The Twins','https://cdn.source.gs/dead-by-daylight/img/k22p01-a72be1.webp'),
    ('Oppression','Whenever you damage a Generator, up to 4 other Generators start regressing. Survivors repairing them get a special Skill Check. Cooldown: 45/40/35 s.','The Twins','https://cdn.source.gs/dead-by-daylight/img/k22p02-6edc96.webp'),
    ('Hex: Crowd Control','The first time a Survivor medium or fast-vaults a Window, a Dull Totem ignites. The last 4/5/6 Windows Survivors medium or fast-vault are blocked. You basic-vault blocked Windows 15% faster. You see the Auras of blocked Windows within 24 m.','The Trickster','https://cdn.source.gs/dead-by-daylight/img/k23p02-d8fd62.webp'),
    ('No Way Out','The first time you Hook each Survivor, you earn 1 Token. When all Generators are completed, when a Survivor starts opening an Exit Gate: - It is blocked 12 s, plus 6/9/12 s for each Token. - You are alerted.','The Trickster','https://cdn.source.gs/dead-by-daylight/img/k23p03-627b03.webp'),
    ('Starstruck','While carrying a Survivor, Survivors within your Terror Radius gain Exposed. This ends 26/28/30 s after: - They leave your Terror Radius. - You drop or Hook the carried Survivor. Cooldown: 60 s.','The Trickster','https://cdn.source.gs/dead-by-daylight/img/k23p01-be9559.webp'),
    ('Eruption','Whenever you damage a Generator, when you down a Survivor, all Generators damaged this way: - Explode, lose 10% progress and start regressing. - Survivors repairing them scream, then you see their Auras for 8/10/12 s. Cooldown: 30 s.','The Nemesis','https://cdn.source.gs/dead-by-daylight/img/k24p03-e67721.webp'),
    ('Hysteria','Whenever a healthy Survivor becomes injured, all injured Survivors gain Oblivious for 30/35/40 s. Cooldown: 20 s.','The Nemesis','https://cdn.source.gs/dead-by-daylight/img/k24p02-a5ddf5.webp'),
    ('Lethal Pursuer','When the trial starts, you see the Auras of all Survivors for 7/8/9 s. Whenever you see a Survivor''s Aura for a duration, it is 2 s longer.','The Nemesis','https://cdn.source.gs/dead-by-daylight/img/k24p01-213b0a.webp'),
    ('Deadlock','Whenever a Generator is completed, the Generator with the most progress is blocked for 15/20/25 s.','The Cenobite','https://cdn.source.gs/dead-by-daylight/img/k25p01-5cba6a.webp'),
    ('Hex: Plaything','The first time you hook each Survivor, they are hexed and a Dull Totem ignites. For 90 s, the Hex Totem is blocked to other Survivors. The hexed Survivors: - Gain Oblivious. - Within 24/20/16 m of the Hex Totem, they see its Aura.','The Cenobite','https://cdn.source.gs/dead-by-daylight/img/k25p02-77d0d8.webp'),
    ('Scourge Hook: Gift of Pain','When the trial starts, 4 random Hooks become Scourge Hooks. Whenever a Survivor is unhooked from a Scourge Hook: - They gain Hemorrhage for 90 s. - They gain Mangled for 90 s. - When they are healed, until they take damage, they heal and repair 10/13/16% slower.','The Cenobite','https://cdn.source.gs/dead-by-daylight/img/k25p03-bb4d9e.webp'),
    ('Grim Embrace','Whenever you Hook a Survivor for the first time, earn 1 Token. When you move 16 m away from the hooked Survivor, all Generators are blocked for 6/8/10 s. When you have 4 Tokens, when you move 16 m away from the hooked Survivor: - All Generators are blocked for 40 s. - You see the Obsession''s Aura for 10 s.','The Artist','https://cdn.source.gs/dead-by-daylight/img/k26p01-1fe56d.webp'),
    ('Hex: Pentimento','You see the Auras of cleansed Totems, and can rekindle each once. Within 16 m, Survivors see the Auras of Rekindled Totems. While a Totem is rekindled, Survivors heal and repair 20% slower, plus 1/2/3% for each additional Rekindled Totem. When all 5 Totems are rekindled at once, they are blocked.','The Artist','https://cdn.source.gs/dead-by-daylight/img/k26p03-73eec4.webp'),
    ('Scourge Hook: Pain Resonance','When the trial starts: - 4 random Hooks become Scourge Hooks. - You earn 4 Tokens. The first time each Survivor is hooked on a Scourge Hook, spend 1 Token, then the Generator with the most progress: - Explodes, loses 10/15/20% progress and starts regressing. - Survivors repairing it scream.','The Artist','https://cdn.source.gs/dead-by-daylight/img/k26p02-d81eed.webp'),
    ('Call of Brine','Whenever you damage a Generator, it regresses 30/40/50% faster for 90 s. For that time, whenever a Survivor hits a good basic Skill Check while repairing that Generator, you are alerted.','The Onryō','https://cdn.source.gs/dead-by-daylight/img/k27p02-a44f58.webp'),
    ('Merciless Storm','The first time each Generator has 90% progress: Survivors repairing it get special Skill Checks. If they miss one of these or stop repairing, that Generator is blocked for 16/18/20 s.','The Onryō','https://cdn.source.gs/dead-by-daylight/img/k27p03-12fc3e.webp'),
    ('Scourge Hook: Floods of Rage','When the trial starts, 4 random Hooks become Scourge Hooks. Whenever a Survivor is unhooked from a Scourge Hook, you see the Auras of other Survivors for 5/6/7 s.','The Onryō','https://cdn.source.gs/dead-by-daylight/img/k27p01-c8d84f.webp'),
    ('Darkness Revealed','Whenever you search a Locker, you see the Auras of Survivors within 8 m of Lockers for 6/7/8 s. Cooldown: 30 s.','The Dredge','https://cdn.source.gs/dead-by-daylight/img/k28p02-da4448.webp'),
    ('Dissolution','3 s after a Survivor takes damage from a basic-attack, for 13/14/15 s, the next time a Survivor fast-vaults a Pallet while within your Terror Radius, it is destroyed.','The Dredge','https://cdn.source.gs/dead-by-daylight/img/k28p01-140875.webp'),
    ('Septic Touch','While a Survivor within your Terror Radius is healing: - They gain Blindness. - They gain Exhausted. When they stop healing, this ends after 20/25/30 s.','The Dredge','https://cdn.source.gs/dead-by-daylight/img/k28p03-1d17bd.webp'),
    ('Awakened Awareness','While carrying a Survivor, within 16/18/20 m of you, you see the Auras of other Survivors.','The Mastermind','https://cdn.source.gs/dead-by-daylight/img/k29p02-4e4804.webp'),
    ('Superior Anatomy','Whenever a Survivor medium or fast-vaults within 12 m of you, the next time you basic-vault a Window, you basic-vault Windows 30/35/40% faster for 10 s. Cooldown: 20 s.','The Mastermind','https://cdn.source.gs/dead-by-daylight/img/k29p01-22c5a5.webp'),
    ('Terminus','When all Generators are completed: all injured, downed, and hooked Survivors gain Broken. When an Exit Gate is opened, this ends after 35/40/45 s.','The Mastermind','https://cdn.source.gs/dead-by-daylight/img/k29p03-3ffd85.webp'),
    ('Hex: Face the Darkness','Whenever you damage a Survivor, they are hexed and a Dull Totem ignites. Every 35/30/25 s, other Survivors not within your Terror Radius scream, then you see their Auras for 2 s. When the hexed Survivor is downed or becomes healthy, the Hex Totem is extinguished.','The Knight','https://cdn.source.gs/dead-by-daylight/img/k30p02-3fe880.webp'),
    ('Hubris','Whenever you are stunned by a Survivor, they gain Exposed for 20/25/30 s. Cooldown: 20 s.','The Knight','https://cdn.source.gs/dead-by-daylight/img/k30p03-a1082e.webp'),
    ('Nowhere to Hide','Whenever you damage a Generator, for 3/4/5 s, you see the Auras of Survivors within 24 m of it.','The Knight','https://cdn.source.gs/dead-by-daylight/img/k30p01-d5fb43.webp'),
    ('Game Afoot','While chasing the Obsession, whenever you basic-break Pallets or Breakable Walls, or damage Generators, you gain 10% Haste for 8/9/10 s. Whenever you damage the Survivor with the most chase time with a basic-attack, they become the Obsession.','The Skull Merchant','https://cdn.source.gs/dead-by-daylight/img/k31p01-0f3b16.webp'),
    ('Leverage','Whenever a Survivor unhooks another or themselves, they heal 20/25/30% slower for 60 s.','The Skull Merchant','https://cdn.source.gs/dead-by-daylight/img/k31p03-329f59.webp'),
    ('THWACK!','When the trial starts, you earn 3 Tokens, up to 3. Whenever you hook a Survivor, you earn 1 Token. Whenever you break a Pallet or Breakable Wall, spend 1 Token. Then, all Survivors within 36 m scream and you see their Auras for 4/5/6 s.','The Skull Merchant','https://cdn.source.gs/dead-by-daylight/img/k31p02-a2238a.webp'),
    ('Forced Hesitation','Whenever you down a Survivor, other Survivors within 16 m of the downed Survivor gain 20% Hindered for 10 s. Cooldown: 40/35/30 s.','The Singularity','https://cdn.source.gs/dead-by-daylight/img/k32p02-c0a6af.webp'),
    ('Genetic Limits','Whenever a Survivor takes damage, they gain Exhausted for 6/7/8 s.','The Singularity','https://cdn.source.gs/dead-by-daylight/img/k32p01-d8dfcd.webp'),
    ('Machine Learning','Whenever you damage a Generator, it becomes compromised. When any compromised Generator is completed by Survivors: - You gain 8% Haste for 40/50/60 s. - You gain Undetectable for 40/50/60 s. - Other Generators lose compromised. Up to 3 Generators can be compromised at a time.','The Singularity','https://cdn.source.gs/dead-by-daylight/img/k32p03-3cce03.webp'),
    ('Alien Instinct','Whenever you hook a Survivor, the farthest injured Survivor: - Gains Oblivious for 40/50/60 s. - You see their Aura for 8 s.','The Xenomorph','https://cdn.source.gs/dead-by-daylight/img/k33p03-8dee20.webp'),
    ('Rapid Brutality','Whenever you damage a Survivor with a basic-attack, you gain 5% Haste for 8/9/10 s. While chasing a Survivor, you cannot gain Bloodlust.','The Xenomorph','https://cdn.source.gs/dead-by-daylight/img/k33p02-112a75.webp'),
    ('Ultimate Weapon','Whenever you search a Locker, Survivors within 40 m: - Gain Blindness for 30 s. - Scream. Cooldown: 55/50/45 s.','The Xenomorph','https://cdn.source.gs/dead-by-daylight/img/k33p01-469f65.webp'),
    ('Batteries Included','Within 16 m of a completed Generator, you gain 5% Haste. When you leave the range, this ends after 1/3/5 s.','The Good Guy','https://cdn.source.gs/dead-by-daylight/img/k34p03-c48d38.webp'),
    ('Friends ‘Til the End','Whenever you Hook a Survivor that is not the Obsession: - The Obsession gains Exposed for 20 s. - You see the Obsession''s Aura for 6/8/10 s. Whenever you Hook the Obsession, another Survivor: - Screams, then you are alerted. - Becomes the Obsession.','The Good Guy','https://cdn.source.gs/dead-by-daylight/img/k34p02-b3e419.webp'),
    ('Hex: Two Can Play','While this Hex is dull, each time you are blinded or stunned by a Survivor 4/3/2 times, a Dull Totem ignites. Whenever you are blinded or stunned by a Survivor you are not carrying, they are blinded for 1.5 s.','The Good Guy','https://cdn.source.gs/dead-by-daylight/img/k34p01-47b7a7.webp'),
    ('Unbound','Whenever a healthy Survivor becomes injured, for the next 26/28/30 s, whenever you basic-vault a window, gain 5% Haste for 25 s.','The Unknown','https://cdn.source.gs/dead-by-daylight/img/k35p01-fc46b5.webp'),
    ('Undone','Whenever you hook a Survivor, earn 1 Token, up to 3. Whenever you damage a Generator, spend all Tokens. For each Token spent: - The Generator loses 8/9/10% more progress. - The Generator is blocked for 8/9/10 s.','The Unknown','https://cdn.source.gs/dead-by-daylight/img/k35p03-86e8e3.webp'),
    ('Unforeseen','Whenever you damage a Generator: - Your Terror Radius is set to that Generator for 22/26/30 s and its radius is 32 m. - You gain Undetectable for that time. Cooldown: 30 s.','The Unknown','https://cdn.source.gs/dead-by-daylight/img/k35p02-0cf9c7.webp'),
    ('Dark Arrogance','You basic-vault Windows 15/20/25% faster. Your basic-attack cooldown is 10% shorter. Whenever you are blinded or Pallet-stunned, the duration is 25% longer.','The Lich','https://cdn.source.gs/dead-by-daylight/img/k36p03-4d8ac4.webp'),
    ('Languid Touch','Whenever a Survivor within 36 m of you scares a Crow, they gain Exhausted for 6/8/10 s. Cooldown: 5 s.','The Lich','https://cdn.source.gs/dead-by-daylight/img/k36p02-0f5827.webp'),
    ('Weave Attunement','The first time each item is depleted, it is dropped. While a Survivor is within 12 m of a dropped item: - You see their Aura. - They see the item''s Aura. Whenever a Survivor picks-up an item, they gain Oblivious for 20/25/30 s.','The Lich','https://cdn.source.gs/dead-by-daylight/img/k36p01-6165a6.webp'),
    ('Dominance','The first time each Totem is being blessed or cleansed by a Survivor: - It is blocked for 25 s. - They scream. - You see their Aura for 3/4/5 s.','The Dark Lord','https://cdn.source.gs/dead-by-daylight/img/k37p03-1a8700.webp'),
    ('Hex: Wretched Fate','The first time a Generator is completed, a Dull Totem ignites. The Obsession: - Repairs 27/30/33% slower. - Sees the Hex Totem''s Aura within 12 m.','The Dark Lord','https://cdn.source.gs/dead-by-daylight/img/k37p01-046ea8.webp'),
    ('Human Greed','Whenever a Survivor gets within 8 m of a locked Chest, you see their Aura for 3/4/5 s. You can lock unlocked Chests. Cooldown: 10 s. You see the Auras of locked Chests.','The Dark Lord','https://cdn.source.gs/dead-by-daylight/img/k37p02-62b7a5.webp'),
    ('All-Shaking Thunder','Whenever you fall from at least 1.25 m, your lunge-attacks are 75% longer for 15/20/25 s. Cooldown: 5 s.','The Houndmaster','https://cdn.source.gs/dead-by-daylight/img/k38p01-326dfe.webp'),
    ('No Quarter','While self-healing, whenever a Survivor has 75% progress, they get special Skill Checks. If they miss one of these or stop healing, they gain Broken for 20/25/30 s.','The Houndmaster','https://cdn.source.gs/dead-by-daylight/img/k38p03-701e85.webp'),
    ('Scourge Hook: Jagged Compass','When the trial starts, 4 random Hooks become Scourge Hooks. Whenever a Survivor is unhooked, the Hook becomes a Scourge Hook. Whenever you hook a Survivor on a Scourge Hook, for 6/8/10 s, you see the Aura of the Generator with the most progress.','The Houndmaster','https://cdn.source.gs/dead-by-daylight/img/k38p02-fdc546.webp'),
    ('Forever Entwined','Whenever a Survivor takes damage, you earn 1 Token, up to 6/7/8. For each Token: - You hook Survivors 4% faster. - You pick-up and drop Survivors 4% faster.','The Ghoul','https://cdn.source.gs/dead-by-daylight/img/k39p02-0e5207.webp'),
    ('Hex: Nothing But Misery','After you damage Survivors with a basic-attack 4 times, a Dull Totem ignites. Whenever you damage a Survivor with a basic-attack: - They gain 5% Hindered for 10/12.5/15 s. - They vault 10% slower for 10/12.5/15 s.','The Ghoul','https://cdn.source.gs/dead-by-daylight/img/k39p01-e06df4.webp'),
    ('None Are Free','The first time you hook each Survivor, earn 1 Token. When all Generators are completed, for each Token: - Upright Pallets are blocked for 12/14/16 s. - Windows are blocked for 12/14/16 s.','The Ghoul','https://cdn.source.gs/dead-by-daylight/img/k39p03-f8e3ff.webp'),
    ('Haywire','Exit Gate Switches with at least 80% progress regress at 80/90/100% speed. While they are regressing, Survivors see the Exit Gate Lights flicker randomly.','The Animatronic','https://cdn.source.gs/dead-by-daylight/img/k40p03-14f4f1.webp'),
    ('Help Wanted','Whenever you damage a Generator, it is compromised. When any compromised Generator is completed by Survivors: - Your successful basic-attack cooldowns are 25% shorter for 70/80/90 s. - Generators not being repaired regress at 150% speed for 70/80/90 s. - Other Generators lose compromised. Up to 3 Generators can be compromised at a time.','The Animatronic','https://cdn.source.gs/dead-by-daylight/img/k40p01-d76f7f.webp'),
    ('Phantom Fear','Whenever a Survivor within your Terror Radius looks at you, they scream, then you see their Aura for 2 s. Cooldown: 80/70/60 s.','The Animatronic','https://cdn.source.gs/dead-by-daylight/img/k40p02-ea4665.webp'),
    ('Hex: Overture of Doom','When the trial starts, a Dull Totem ignites and hexes the farthest Generator from it. After a Survivor repairs the hexed Generator for 5 seconds: - You gain Undetectable for 20/25/30 s. - For that time, your Terror Radius is set to that Generator. When the hexed Generator is repaired, the next farthest Generator is hexed.','The Krasue','https://cdn.source.gs/dead-by-daylight/img/k41p03-54a6e5.webp'),
    ('Ravenous','The first time you hook each Survivor, you earn 1 Token. For each Token: - Gain 4% Haste while carrying a Survivor. - Hook Survivors 4% faster. When you have 4 Tokens, all Survivors: - Scream. - Gain Exposed for 80/85/90 s.','The Krasue','https://cdn.source.gs/dead-by-daylight/img/k41p01-242fa6.webp'),
    ('Wandering Eye','Whenever you start chasing a Survivor, for the next 5 s, you see the Auras of all other injured Survivors within 20 m. Cooldown: 40/35/30 s.','The Krasue','https://cdn.source.gs/dead-by-daylight/img/k41p02-184c57.webp'),
    ('Hex: Hive Mind','The first time you hook a Survivor, a Dull Totem ignites. The Auras of Generators show their progress. When 1 Generator remains: - All Generators explode, lose 6/8/10% progress and start regressing. - The Hex Totem is extinguished.','The First','https://cdn.source.gs/dead-by-daylight/img/k42p03-0b81c3.webp'),
    ('Secret Project','Whenever a Totem is blessed or cleansed, a random unblocked Generator is blocked for 20/25/30 s. Whenever 1 or more Generators are blocked, you gain Undetectable for 30 s.','The First','https://cdn.source.gs/dead-by-daylight/img/k42p02-8e4d85.webp'),
    ('Turn Back The Clock','After hooking a Survivor, for the next 40/50/60 s, use Active Ability button 1 to make target Generator you can see within 20 m explode, lose 10% progress and start regressing.','The First','https://cdn.source.gs/dead-by-daylight/img/k42p01-e79a2f.webp'),
    ('Hex: Scared to Death','After you hook 3 different Survivors, a Dull Totem ignites. While chasing a Survivor, whenever you basic-break a Pallet, Survivors within 13 m: - Scream. - Gain 11/12/13% Hindered for 3 s.','The Slasher','https://cdn.source.gs/dead-by-daylight/img/k43p01-c470db.webp'),
    ('Rampage','Whenever you basic-break a Pallet or Breakable Wall, you earn 1 Token, up to 13. Whenever you are blinded or Pallet-stunned, for the next 13 s you gain 1% Haste for each Token. Cooldown: 30/25/20.','The Slasher','https://cdn.source.gs/dead-by-daylight/img/k43p03-b19b06.webp'),
    ('Silent Shadow','Whenever you hook a Survivor, you gain Undetectable for 11/12/13 s. When all Generators are completed, you gain Undetectable.','The Slasher','https://cdn.source.gs/dead-by-daylight/img/k43p02-b8de23.webp'),
    ('Celestial Witness','Every 30 s, if the Obsession is at least 40 m away from you, you see their Aura for 2/2.5/3 s. Otherwise, the farthest Survivor becomes the Obsession.','The Judgment','https://cdn.source.gs/dead-by-daylight/img/k44p01-d79b1e.webp'),
    ('Hex: Under Your Thumb','The first time a Survivor gains a Hook State, a Dull Totem ignites. Whenever a running Survivor gains Haste within 32 m of you, you are alerted. Running Survivors cannot gain more than 25/20/15% Haste at a time.','The Judgment','https://cdn.source.gs/dead-by-daylight/img/k44p02-a60f0d.webp'),
    ('Lay Waste','Whenever you damage a Generator, for each Charge it has, it regresses 2% faster. Cooldown: 55/50/45 s.','The Judgment','https://cdn.source.gs/dead-by-daylight/img/k44p03-560d50.webp')
) AS p(nombre,descripcion,owner,imagen)
JOIN public."Killers" k ON k."Nombre" = p.owner;

-- Perks de SURVIVORS
INSERT INTO public."Perks"
    ("Nombre","Descripcion","Nivel","TipoPersonaje","KillerId","SurvivorId","Activo","FechaCreacion","ImagenUrl")
SELECT p.nombre, p.descripcion, 3, 'Survivor', NULL, s."Id", true, now(), p.imagen
FROM (VALUES
    ('Bond','Within 20/28/36 m, you see other Survivors'' Auras.','Dwight Fairfield','https://cdn.source.gs/dead-by-daylight/img/bond-21ff0b.webp'),
    ('Leader','Within 10 m of you, other Survivors: - Cleanse Totems 20/25/30% faster. - Heal 20/25/30% faster. - Open Exit Gates 20/25/30% faster. - Sabotage Hooks 20/25/30% faster. - Unhook Survivors 20/25/30% faster. - Unlock Chests 20/25/30% faster. After they leave your range, this ends after 20 s.','Dwight Fairfield','https://cdn.source.gs/dead-by-daylight/img/leader-0e3ecd.webp'),
    ('Prove Thyself','For each other Survivor within 4 m of you, all Survivors repair 6/8/10% faster.','Dwight Fairfield','https://cdn.source.gs/dead-by-daylight/img/prove-thyself-316071.webp'),
    ('Adrenaline','When all Generators are completed, if you are downed or injured, heal instantly. Then, ignoring Exhausted: - You gain 50% Haste for 4 s. - You gain Exhausted for 60/50/40 s.','Meg Thomas','https://cdn.source.gs/dead-by-daylight/img/adrenaline-9fc396.webp'),
    ('Quick & Quiet','You hide in Lockers and vault silently. The Killer is not alerted. Cooldown: 25/20/15 s.','Meg Thomas','https://cdn.source.gs/dead-by-daylight/img/quickquiet-75be8e.webp'),
    ('Sprint Burst','Whenever you start running: - You gain 50% Haste for 2 s. - You gain Exhausted for 60/50/40 s.','Meg Thomas','https://cdn.source.gs/dead-by-daylight/img/sprint-burst-00f229.webp'),
    ('Botany Knowledge','You heal 30/40/50% faster.','Claudette Morel','https://cdn.source.gs/dead-by-daylight/img/botany-knowledge-90d033.webp'),
    ('Empathy','Within 64/96/128 m, you see the Auras of injured Survivors.','Claudette Morel','https://cdn.source.gs/dead-by-daylight/img/empathy-55946b.webp'),
    ('Self-Care','You can heal yourself, but 75/70/65% slower.','Claudette Morel','https://cdn.source.gs/dead-by-daylight/img/self-care-d18fbb.webp'),
    ('Calm Spirit','You do not scare Crows or scream. You bless and cleanse Totems, and unlock Chests silently, and 8/9/10% faster.','Jake Park','https://cdn.source.gs/dead-by-daylight/img/calm-spirit-5815a7.webp'),
    ('Iron Will','While injured and not Exhausted, your Grunts of Pain are 80/90/100% quieter.','Jake Park','https://cdn.source.gs/dead-by-daylight/img/iron-will-b2608d.webp'),
    ('Saboteur','Within 56 m of where another Survivor was picked-up by the Killer and is being carried, you see the Auras of Hooks and Scourge Hooks. You can sabotage Hooks. Cooldown: 70/65/60 s.','Jake Park','https://cdn.source.gs/dead-by-daylight/img/saboteur-81ad0c.webp'),
    ('Balanced Landing','Whenever you fall from at least 1.25 m: - You gain 50% Haste for 3 s. - You gain Exhausted for 60/50/40 s. - Your stagger is 75% shorter. - Your Grunts from falling are 100% quieter.','Nea Karlsson','https://cdn.source.gs/dead-by-daylight/img/balanced-landing-115288.webp'),
    ('Streetwise','The first time you deplete an item''s Charges, you see the Killer''s Aura for 8 s. Whenever you loot an item from a Chest, it has 60/70/80% more Charges.','Nea Karlsson','https://cdn.source.gs/dead-by-daylight/img/streetwise-ebe088.webp'),
    ('Urban Evasion','While crouched, you gain 90/95/100% Haste.','Nea Karlsson','https://cdn.source.gs/dead-by-daylight/img/urban-evasion-5df5ea.webp'),
    ('Decisive Strike','Until all Generators are completed, whenever you are unhooked, for the next 40/50/60 s: when the Killer picks you up, once per trial, hit a Special Skill check: - Stun the Killer for 4 s. - Become the Obsession. This is disabled by conspicuous actions. At the start of the trial, you are more likely to be the Obsession.','Laurie Strode','https://cdn.source.gs/dead-by-daylight/img/decisivestrike-334c3a.webp'),
    ('Object of Obsession','While you are the Obsession, every 30 s, the Killer sees your Aura for 4 s. While the Killer sees your Aura: - You see their Aura. - You bless and cleanse Totems 8/9/10% faster. - You heal 8/9/10% faster. - You repair 8/9/10% faster. When the trial starts, you are more likely to be the Obsession.','Laurie Strode','https://cdn.source.gs/dead-by-daylight/img/objectofobsession-a7f83e.webp'),
    ('Sole Survivor','Whenever you are hooked or complete a Generator, you earn 1 Token, up to 6. For each Token, other Survivors open Exit Gates 10% faster. When you are the last Survivor, if you have at least 3 Tokens: - You can unlock the Hatch. - For each Token, the Killer cannot see your Aura for 6/8/10 s.','Laurie Strode','https://cdn.source.gs/dead-by-daylight/img/solesurvivor-a73421.webp'),
    ('Ace in the Hole','Whenever you loot an item from a Chest, it will have: - A Visceral or lower rarity add-on. - 50/75/100% chance for an Uncommon or lower rarity add-on. When you escape, you keep your add-ons.','Ace Visconti','https://cdn.source.gs/dead-by-daylight/img/ace-in-the-hole-c03a3a.webp'),
    ('Open-Handed','All Survivors see Auras that have a range from 8/12/16 m farther.','Ace Visconti','https://cdn.source.gs/dead-by-daylight/img/open-handed-a40bce.webp'),
    ('Up the Ante','For each other Survivor alive, all Survivors are 1/2/3% luckier. All Survivors can attempt to unhook themselves.','Ace Visconti','https://cdn.source.gs/dead-by-daylight/img/up-the-ante-9f649c.webp'),
    ('Borrowed Time','Whenever you unhook a Survivor: - They retain their unhook Endurance for 6/8/10 s longer. - They retain their unhook Haste for 10 s longer.','Bill Overbeck','https://cdn.source.gs/dead-by-daylight/img/borrowedtime-1b2d7e.webp'),
    ('Left Behind','When all other Survivors are dead, while within 24/28/32 m of the Hatch, you see its Aura.','Bill Overbeck','https://cdn.source.gs/dead-by-daylight/img/leftbehind-8f3970.webp'),
    ('Unbreakable','Once per trial, while downed by the Killer, you can fully recover. While downed, you recover 25/30/35% faster.','Bill Overbeck','https://cdn.source.gs/dead-by-daylight/img/selfsufficient-1e8338.webp'),
    ('Alert','Whenever the Killer breaks a Pallet or Breakable Wall, or damages a Generator: - You hear a sound cue. - You see their Aura for 3/4/5 s.','Feng Min','https://cdn.source.gs/dead-by-daylight/img/alert-174fb5.webp'),
    ('Lithe','Whenever you medium or fast-vault: - You gain 50% Haste for 3 s. - You gain Exhausted for 60/50/40 s.','Feng Min','https://cdn.source.gs/dead-by-daylight/img/lithe-42d6f7.webp'),
    ('Technician','While repairing a Generator: - The range of Generator repair noises is 16 m shorter. - Whenever you miss a basic Skill Check, the Generator does not explode, but loses 4/3/2% more progress.','Feng Min','https://cdn.source.gs/dead-by-daylight/img/technician-0f4e79.webp'),
    ('Dead Hard','Whenever you are unhooked, while injured and running, use Active Ability button 1: - You gain Endurance for 0.5 s. - You gain Exhausted for 60/50/40 s.','David King','https://cdn.source.gs/dead-by-daylight/img/deadhard-7272b6.webp'),
    ('No Mither','When the trial starts, you become injured, then: - You gain Broken. - Your Grunts of Pain are 100% quieter. - You leave no Pools of Blood. - You recover 15/20/25% faster. - You can fully recover.','David King','https://cdn.source.gs/dead-by-daylight/img/nomither-f4860d.webp'),
    ('We''re Gonna Live Forever','You heal downed Survivors 100% faster. Whenever you finish healing a downed Survivor, they gain Endurance for 6/8/10 s. Cooldown: 30 s.','David King','https://cdn.source.gs/dead-by-daylight/img/weregonnaliveforever-85dddf.webp'),
    ('Boil Over','While carried by the Killer: - Whenever the Killer falls from at least 1.25 m, you gain 33% of your current wiggle progress. - Your wiggle is 60/70/80% stronger. - Within 16 m, the Killer cannot see Hook Auras.','Kate Denson','https://cdn.source.gs/dead-by-daylight/img/boilover-156f1e.webp'),
    ('Dance With Me','Whenever you fast-exit a Locker, medium-vault, or fast-vault, you leave no Scratch Marks for 5 s. Cooldown: 25/20/15 s.','Kate Denson','https://cdn.source.gs/dead-by-daylight/img/dance-with-me-4ab1af.webp'),
    ('Windows of Opportunity','Within 24 m of you see the Auras of Windows. You vault Windows 10% faster. Whenever you vault a Window, cooldown: 40/35/30 s.','Kate Denson','https://cdn.source.gs/dead-by-daylight/img/windowsofopportunity-f33c23.webp'),
    ('Pharmacy','Whenever you unlock a Chest, it will contain a rare Med-Kit. You unlock and rummage Chests 75/100/125% faster. You can rummage each Chest 1 time. The range at which the Killer hears you unlocking Chests is 12 m shorter.','Quentin Smith','https://cdn.source.gs/dead-by-daylight/img/pharmacy-8d9541.webp'),
    ('Vigil','All Survivors within 16 m of you lose Exhausted 20/25/30% faster. This effect ends 15 s after they leave your range.','Quentin Smith','https://cdn.source.gs/dead-by-daylight/img/vigil-bd113a.webp'),
    ('Wake Up!','When all Generators are completed: - You see the Auras of Exit Gate Switches. - While opening an Exit Gate, other Survivors see your Aura. - You open Exit Gates 8/9/10% faster, and an additional 20% faster for each other Survivor alive.','Quentin Smith','https://cdn.source.gs/dead-by-daylight/img/wakeup-c2baf5.webp'),
    ('Detective''s Hunch','Whenever a Generator is completed, for 20 s, within 32/48/64 m of you: - You see the Auras of Chests. - You see the Auras of Generators. - You see the Auras of Totems.','David Tapp','https://cdn.source.gs/dead-by-daylight/img/detectiveshunch-f59b82.webp'),
    ('Stake Out','After hiding for 15 s within 24 m of the Killer, while in their Terror Radius, you earn 1 Token, up to 2/3/4. While you have at least 1 Token, basic Skill Checks are replaced by special Skill Checks. Special Skill Checks grant + 4% more progress. Whenever you hit or miss a special Skill Check, spend 1 Token.','David Tapp','https://cdn.source.gs/dead-by-daylight/img/stakeout-4ca674.webp'),
    ('Tenacity','While downed: - You gain 30/40/50% Haste. - You can crawl and recover at the same time. - Your Grunts of Pain are 75% quieter. - The Killer cannot see your Aura.','David Tapp','https://cdn.source.gs/dead-by-daylight/img/tenacity-dbed34.webp'),
    ('Autodidact','You start the trial with 0 Tokens, up to 3/4/5, and your good basic healing Skill Checks give 15% less progress. While healing another Survivor without a Med-Kit: - Whenever you hit a basic Skill Check, you earn 1 token. - Whenever you hit a basic Skill Check, for each Token, you gain 15% more progress. - You cannot get great basic Skill Checks.','Adam Francis','https://cdn.source.gs/dead-by-daylight/img/autodidact-cee851.webp'),
    ('Deliverance','Once per trial, when you safely unhook another Survivor, you can unhook yourself. When you unhook yourself this way, you gain Broken for 160/140/120 s.','Adam Francis','https://cdn.source.gs/dead-by-daylight/img/deliverance-6af50e.webp'),
    ('Diversion','After hiding for 30/25/20 s within the Killer''s Terror Radius, while crouched and idle, use Active Ability button 1 to throw a pebble 20 m away: - The Killer is alerted. - The pebble leaves Scratch Marks.','Adam Francis','https://cdn.source.gs/dead-by-daylight/img/diversion-99736c.webp'),
    ('Aftercare','You and up to 1/2/3 Survivors see each other''s Auras whenever: - You unhook them, or they unhook you. - You finish healing them, or they finish healing you. This effect lasts until you are hooked.','Jeff Johansen','https://cdn.source.gs/dead-by-daylight/img/aftercare-efeea0.webp'),
    ('Breakdown','Whenever you are unhooked: - The Hook breaks, then is repaired after 180 s. - You see the Killer''s Aura for 4/5/6 s.','Jeff Johansen','https://cdn.source.gs/dead-by-daylight/img/breakdown-13aad1.webp'),
    ('Distortion','When the trial starts, and after being chased for 15 s, you earn 1 Token, up to 2. While not downed, whenever the Killer attempts to see your Aura, spend 1 Token. Then, for the next 8/10/12 s: - The Killer cannot see your Aura. - You leave no Scratch Marks.','Jeff Johansen','https://cdn.source.gs/dead-by-daylight/img/distortion-c2de1f.webp'),
    ('Head On','After hiding in a Locker for 3 s, fast-exit to stun the Killer for 3 s if they are within 2.5 m, then gain Exhausted for 60/50/40 s.','Jane Romero','https://cdn.source.gs/dead-by-daylight/img/headon-3b409b.webp'),
    ('Poised','The first time you start repairing each Generator, you see the Killer''s Aura for 8 s. Whenever a Generator is completed, you leave no Scratch Marks for 20/25/30 s.','Jane Romero','https://cdn.source.gs/dead-by-daylight/img/poised-beab9d.webp'),
    ('Solidarity','While injured and healing another Survivor, you also gain healing progress at 65/70/75% speed.','Jane Romero','https://cdn.source.gs/dead-by-daylight/img/solidarity-e6adb1.webp'),
    ('Buckle Up','While healing a downed Survivor, you both see the Killer''s Aura. Whenever you finish healing a downed Survivor or fully recover: - The Survivor gains 50% Haste for 3/4/5 s. - The Survivor leaves no Scratch Marks for 3/4/5 s.','Ash Williams','https://cdn.source.gs/dead-by-daylight/img/buckleup-5c65a1.webp'),
    ('Flip-Flop','While downed, whenever the Killer picks you up, 50% of your recovery progress is added to your wiggle progress, up to 40/45/50%.','Ash Williams','https://cdn.source.gs/dead-by-daylight/img/flipflop-11c153.webp'),
    ('Mettle of Man','After taking 3 protection hits, while injured and until you go down, the next time you would be downed by the Killer, take no damage instead. When you become healthy, while you are at least 12/14/16 m from the Killer, they see your Aura. When the trial starts, you are more likely to be the Obsession.','Ash Williams','https://cdn.source.gs/dead-by-daylight/img/themettleofman-56ee35.webp'),
    ('Better Together','While you are repairing a Generator: - Other Survivors see that Generator''s Aura. - Whenever the Killer downs a Survivor, you see the Auras of all Survivors for 20/25/30 s.','Nancy Wheeler','https://cdn.source.gs/dead-by-daylight/img/bettertogether-9937b3.webp'),
    ('Fixated','While walking, you gain 10/15/20% Haste. You see your own Scratch Marks.','Nancy Wheeler','https://cdn.source.gs/dead-by-daylight/img/fixated-ec8718.webp'),
    ('Inner Strength','Whenever you cleanse a Totem, while injured and not Broken, after hiding in a Locker for 10/9/8 s, you become healthy instantly.','Nancy Wheeler','https://cdn.source.gs/dead-by-daylight/img/innerstrength-68d06b.webp'),
    ('Babysitter','Whenever you unhook a Survivor: - They gain 10% Haste for 20/25/30 s. - They leave no Pools of Blood for 20/25/30 s. - They leave no Scratch Marks for 20/25/30 s. - You see the Killer''s Aura for 8 s.','Steve Harrington','https://cdn.source.gs/dead-by-daylight/img/babysitter-15705d.webp'),
    ('Camaraderie','While you are struggling on Hook, when another Survivor gets within 16 m, the timer is paused for 26/30/34 s.','Steve Harrington','https://cdn.source.gs/dead-by-daylight/img/camaraderie-fa105f.webp'),
    ('Second Wind','After you heal 1 Survivor, while not Broken, when you are unhooked, you gain Broken. After 28/24/20 s, if you are not downed, you are instantly healed.','Steve Harrington','https://cdn.source.gs/dead-by-daylight/img/secondwind-da8ad8.webp'),
    ('Any Means Necessary','While next to a Dropped Pallet, use Active Ability button 1 for 5/4/3 s to reset it. You see the Auras of Dropped Pallets.','Yui Kimura','https://cdn.source.gs/dead-by-daylight/img/anymeansnecessary-248b12.webp'),
    ('Breakout','Within 5 m of a carried Survivor: - You gain 6/8/10% Haste. - The carried Survivor wiggles 25% faster.','Yui Kimura','https://cdn.source.gs/dead-by-daylight/img/breakout-b18564.webp'),
    ('Lucky Break','While injured, for up to 40/50/60 s: - You leave no Pools of Blood. - You leave no Scratch Marks. For each second spent healing another Survivor, recharge the duration by 1 s.','Yui Kimura','https://cdn.source.gs/dead-by-daylight/img/luckybreak-4c5b0a.webp'),
    ('For the People','While healthy and healing another Survivor without a Med-Kit, use Active Ability button 1 to heal them instantly: - You take damage. - You gain Broken for 80/70/60 s. - You become the Obsession. When the trial starts, you are less likely to be the Obsession.','Zarina Kassir','https://cdn.source.gs/dead-by-daylight/img/forthepeople-03cef2.webp'),
    ('Off the Record','Until all Generators are completed, whenever you are unhooked, for the next 30/35/40 s: - You gain Endurance. - Your Grunts of Pain are 100% quieter. - The Killer cannot see your Aura.','Zarina Kassir','https://cdn.source.gs/dead-by-daylight/img/offtherecord-e47739.webp'),
    ('Red Herring','After you repair a Generator for at least 1 s, you see its Aura. When you hide in a Locker, the Killer is alerted to the Generator. Cooldown: 25/20/15 s.','Zarina Kassir','https://cdn.source.gs/dead-by-daylight/img/redherring-294828.webp'),
    ('Blood Pact','While you are not the Obsession: - While you or the Obsession are injured, you see each other''s Auras. - Whenever you finish healing the Obsession, or they finish healing you, while within 16 m of each other, you both gain 5/6/7% Haste. While you are the Obsession, if you are hooked, another Survivor becomes the Obsession. When the trial starts, you are less likely to be the Obsession.','Cheryl Mason','https://cdn.source.gs/dead-by-daylight/img/bloodpact-e2558d.webp'),
    ('Repressed Alliance','After repairing Generators for 40/35/30 s, while repairing a Generator alone, use Active Ability button 1 to block that generator for 15 s.','Cheryl Mason','https://cdn.source.gs/dead-by-daylight/img/repressedalliance-ec12f2.webp'),
    ('Soul Guard','While hexed, you can fully recover. Whenever you fully recover, you gain Endurance for 4/6/8 s. Cooldown: 30 s.','Cheryl Mason','https://cdn.source.gs/dead-by-daylight/img/soulguard-f6e2cf.webp'),
    ('Built to Last','While holding a depleted item, after hiding in a Locker for 14/12/10 s, it is recharged to 99%. Each time you recharge an item this way, it recharges 33% fewer Charges.','Felix Richter','https://cdn.source.gs/dead-by-daylight/img/builttolast-abbd45.webp'),
    ('Desperate Measures','For each injured, downed, or hooked Survivor: - You heal 16/18/20% faster. - You unhook 16/18/20% faster.','Felix Richter','https://cdn.source.gs/dead-by-daylight/img/desperatemeasures-cf4d99.webp'),
    ('Visionary','Within 32 m of you, you see the Auras of Generators. Whenever a Generator is completed, cooldown: 20/18/16 s.','Felix Richter','https://cdn.source.gs/dead-by-daylight/img/visionary-70348d.webp'),
    ('Appraisal','When the trial starts, you earn 4 Tokens. Spend 1 Token to rummage an empty Chest, up to 2 times per Chest. You rummage Chests 40/60/80% faster.','Élodie Rakoto','https://cdn.source.gs/dead-by-daylight/img/s24p01-a06ce9.webp'),
    ('Deception','Whenever you attempt to fast-enter a Locker: - You do not enter the Locker. - The Killer is alerted. - You leave no Pools of Blood for 5 s. - You leave no Scratch Marks for 5 s. Cooldown: 25/20/15 s.','Élodie Rakoto','https://cdn.source.gs/dead-by-daylight/img/s24p02-d40fed.webp'),
    ('Power Struggle','While carried by the Killer, while you have at least 25/20/15% wiggle and next to an Upright Pallet, you can drop it to stun the Killer. While downed, you see the Auras of Upright Pallets.','Élodie Rakoto','https://cdn.source.gs/dead-by-daylight/img/s24p03-ff86d7.webp'),
    ('Fast Track','Whenever you unhook another Survivor, you earn 1 Token, up to 1/2/3. While repairing, whenever you hit a great basic Skill Check, spend all Tokens. For each Token spent, the Generator gains 5% permanent progress.','Yun-Jin Lee','https://cdn.source.gs/dead-by-daylight/img/s25p01-b7988c.webp'),
    ('Self-Preservation','Whenever another Survivor is hooked, you gain Elusive for 13/14/15 s.','Yun-Jin Lee','https://cdn.source.gs/dead-by-daylight/img/s25p03-51bf29.webp'),
    ('Smash Hit','Whenever you Pallet-stun the Killer: - You gain 50% Haste for 4 s. - You gain Exhausted for 30/25/20 s.','Yun-Jin Lee','https://cdn.source.gs/dead-by-daylight/img/s25p02-d3133a.webp'),
    ('Blast Mine','After repairing 40% of Generators, while next to a Generator, use Active Ability button 2 to trap it for 100/110/120 s. All Survivors see that Generator''s Aura for that time. When the Killer damages that Generator, the trap explodes, then: - They are stunned for 4 s. - Everyone nearby looking at the detonation is blinded.','Jill Valentine','https://cdn.source.gs/dead-by-daylight/img/s26p03-e55426.webp'),
    ('Counterforce','When the trial starts, you earn 1 Token. Whenever you cleanse a Totem, earn 1 Token, then, you see the Aura of the farthest Totem for 10/12/14 s. For each Token, you cleanse Totems 25% faster.','Jill Valentine','https://cdn.source.gs/dead-by-daylight/img/s26p01-baf555.webp'),
    ('Resurgence','Whenever you are unhooked, you gain 50/60/70% healing progress.','Jill Valentine','https://cdn.source.gs/dead-by-daylight/img/s26p02-429c9a.webp'),
    ('Bite the Bullet','While healing, you and the healed Survivor make no noises or Grunts of Pain. Whenever you miss a basic Skill Check: - You lose only 3/2/1% progress. - The Killer is not alerted.','Leon S. Kennedy','https://cdn.source.gs/dead-by-daylight/img/s27p01-f9c76f.webp'),
    ('Flashbang','After repairing 50/45/40% of Generators, while hiding in a Locker, use Active Ability button 1 to craft a Flashbang. When you use the Flashbang: - Everyone nearby looking at the detonation is blinded. - The Killer is alerted.','Leon S. Kennedy','https://cdn.source.gs/dead-by-daylight/img/s27p02-0b560f.webp'),
    ('Rookie Spirit','After you hit 5/4/3 basic repair Skill Checks, while a Generator is regressing, you see its Aura.','Leon S. Kennedy','https://cdn.source.gs/dead-by-daylight/img/s27p03-678542.webp'),
    ('Boon: Circle of Healing','While next to a Totem, use Active Ability button 1 to bless it, creating a unique Boon Totem that combines all your Boons. Survivors within the Boon''s range: - While healing without a Med-Kit, they heal others 50/75/100% faster. - While injured, other Survivors see their Aura.','Mikaela Reid','https://cdn.source.gs/dead-by-daylight/img/s28p02-e410ae.webp'),
    ('Boon: Shadow Step','While next to a Totem, use Active Ability button 1 to bless it, creating a unique Boon Totem that combines all your Boons. Survivors within the Boon''s range: - Leave no Scratch Marks. - Their Auras cannot be seen by the Killer. When leaving the range, this ends after 2/3/4 s.','Mikaela Reid','https://cdn.source.gs/dead-by-daylight/img/s28p03-c65ec7.webp'),
    ('Clairvoyance','Whenever you bless or cleanse a Totem, while not holding an item, use Use Item button to, for up to 10/11/12 s and within 64 m: - See the Auras of Chests. - See the Auras of Exit Gate Switches. - See the Auras of Generators. - See the Aura of the Hatch. - See the Auras of Hooks.','Mikaela Reid','https://cdn.source.gs/dead-by-daylight/img/s28p01-afa84e.webp'),
    ('Boon: Exponential','While next to a Totem, use Active Ability button 1 to bless it, creating a unique Boon Totem that combines all your Boons. Downed Survivors within the Boon''s range: - Recover 90/95/100% faster. - Can fully recover.','Jonah Vasquez','https://cdn.source.gs/dead-by-daylight/img/s29p03-0cb6e8.webp'),
    ('Corrective Action','When the trial starts, you earn 1/2/3 Tokens, up to 5. Whenever you hit a great basic Skill Check, earn 1 Token. Whenever another Survivor misses a basic Skill Check, spend 1 Token: - The missed Skill Check becomes a good Skill Check. - You see that Survivor''s Aura for 6 s.','Jonah Vasquez','https://cdn.source.gs/dead-by-daylight/img/s29p02-40b4cc.webp'),
    ('Overcome','Whenever you take damage: - You retain your speed boost for 2 s longer. - You gain Exhausted for 60/50/40 s.','Jonah Vasquez','https://cdn.source.gs/dead-by-daylight/img/s29p01-0ed47e.webp'),
    ('Boon: Dark Theory','While next to a Totem, use Active Ability button 1 to bless it, creating a unique Boon Totem that combines all your Boons. Survivors within the Boon''s range gain 3% Haste. When leaving the range, this ends after 2/3/4 s.','Yoichi Asakawa','https://cdn.source.gs/dead-by-daylight/img/s30p03-506c49.webp'),
    ('Empathic Connection','You heal other Survivors 30/35/40% faster. Injured Survivors see your Aura.','Yoichi Asakawa','https://cdn.source.gs/dead-by-daylight/img/s30p02-7305c8.webp'),
    ('Parental Guidance','Whenever you stun the Killer, for 5/6/7 s: - You make no Grunts of Pain. - You leave no Pools of Blood. - You leave no Scratch Marks.','Yoichi Asakawa','https://cdn.source.gs/dead-by-daylight/img/s30p01-546306.webp'),
    ('Inner Focus','Whenever the Killer damages another Survivor, you see the Killer''s Aura for 6/8/10 s. You see other Survivors'' Scratch Marks.','Haddie Kaur','https://cdn.source.gs/dead-by-daylight/img/s31p01-bb733e.webp'),
    ('Overzealous','Whenever you bless or cleanse a Totem, until you take damage, you repair 8/9/10% faster. If that Totem was a Hex Totem, the effect is doubled.','Haddie Kaur','https://cdn.source.gs/dead-by-daylight/img/s31p03-e32241.webp'),
    ('Residual Manifest','Whenever you blind the Killer, they gain Blindness for 20/25/30 s. You can rummage Chests 1 time. The first time you rummage a Chest, it will contain an uncommon Flashlight.','Haddie Kaur','https://cdn.source.gs/dead-by-daylight/img/s31p02-09db69.webp'),
    ('Low Profile','When all other Survivors are downed or hooked, for 70/80/90 s: - You make no Grunts of Pain. - You leave no Pools of Blood. - You leave no Scratch Marks.','Ada Wong','https://cdn.source.gs/dead-by-daylight/img/s32p03-473a3c.webp'),
    ('Reactive Healing','While injured, whenever another Survivor within 32 m of you takes damage, you gain 40/45/50% missing healing progress.','Ada Wong','https://cdn.source.gs/dead-by-daylight/img/s32p02-808945.webp'),
    ('Wiretap','After repairing 40% of Generators, while next to a Generator, use Active Ability button 2 to trap it for 100/110/120 s or until the Killer damages that Generator. All Survivors see that Generator''s Aura for that time. While the Killer is within 14 m of that Generator, all Survivors see the Killer''s Aura.','Ada Wong','https://cdn.source.gs/dead-by-daylight/img/s32p01-7a8546.webp'),
    ('Better Than New','Whenever you finish healing another Survivor, until they take damage: - They bless and cleanse Totems 40/45/50% faster. - They heal 40/45/50% faster. - They unlock Chests 40/45/50% faster.','Rebecca Chambers','https://cdn.source.gs/dead-by-daylight/img/s33p01-3da6e6.webp'),
    ('Hyperfocus','Whenever you hit a great basic Skill Check, you earn 1 Token, up to 6. For each Token, basic Skill Checks: - Appear 4% more often. - Spin 4% faster. - Whenever you hit a great, give 10/20/30% more progress. Whenever you miss a basic Skill Check, hit a good Skill Check, or stop healing or repairing, lose all Tokens.','Rebecca Chambers','https://cdn.source.gs/dead-by-daylight/img/s33p03-f8c821.webp'),
    ('Reassurance','Once per Hook State, while within 6 m of a hooked Survivor, use Active Ability button 2 to stop the sacrifice progress for 20/25/30 s.','Rebecca Chambers','https://cdn.source.gs/dead-by-daylight/img/s33p02-38ca11.webp'),
    ('Fogwise','While repairing, whenever you hit a great basic Skill Check, you see the Killer''s Aura for 4/5/6 s.','Vittorio Toscano','https://cdn.source.gs/dead-by-daylight/img/s34p02-e90735.webp'),
    ('Potential Energy','While repairing, use Active Ability button 2 to earn Tokens instead of progress, up to 10/15/20 Tokens. While you have at least 1 Token, Active Ability button 2 to spend all Tokens and gain 1% progress for each Token spent. Whenever you take damage, lose all Tokens.','Vittorio Toscano','https://cdn.source.gs/dead-by-daylight/img/s34p01-c46a5a.webp'),
    ('Quick Gambit','While chased by the Killer: - You see the Auras of other Survivors. - Other Survivors repair 3/4/5% faster. Whenever you take damage, cooldown: 40 s.','Vittorio Toscano','https://cdn.source.gs/dead-by-daylight/img/s34p03-47f436.webp'),
    ('Cut Loose','While chased by the Killer, whenever you medium or fast-vault: - For up to 4/5/6 s, your medium and fast vaults are silent. - During that time, whenever you medium or fast-vault, the timer is reset. Cooldown: 45 s.','Thalita Lyra','https://cdn.source.gs/dead-by-daylight/img/s35p01-69d801.webp'),
    ('Friendly Competition','Whenever you finish repairing a Generator with at least 1 other Survivor, Survivors who finished repairing it repair 10% faster for 80/85/90 s.','Thalita Lyra','https://cdn.source.gs/dead-by-daylight/img/s35p02-168504.webp'),
    ('Teamwork: Power of Two','Whenever you finish healing another Survivor, while you stay within 8/12/16 m of each other, you both gain 5% Haste. When either of you leaves the range, this ends after 4 s.','Thalita Lyra','https://cdn.source.gs/dead-by-daylight/img/s35p03-effe69.webp'),
    ('Background Player','Whenever the Killer picks-up another Survivor, for the next 10 s, when you start running: - Gain 50% Haste for 5 s. - Gain Exhausted for 30/25/20 s.','Renato Lyra','https://cdn.source.gs/dead-by-daylight/img/s36p01-ee78e1.webp'),
    ('Blood Rush','Until all Generators are completed, whenever you are unhooked, for the next 40/50/60 s, while Exhausted, use Active Ability button 1 to lose Exhausted instantly. This is disabled by conspicuous actions.','Renato Lyra','https://cdn.source.gs/dead-by-daylight/img/s36p02-f18d1a.webp'),
    ('Teamwork: Collective Stealth','Whenever another Survivor finishes healing you, while within 8/12/16 m of each other, you both leave no Scratch Marks. When either of you leaves the range, this ends after 4 s.','Renato Lyra','https://cdn.source.gs/dead-by-daylight/img/s36p03-164703.webp'),
    ('Made for This','While injured, whenever you finish healing another Survivor, you gain Endurance for 6/8/10 s. While you are running and have Deep Wound, you gain 3% Haste.','Gabriel Soma','https://cdn.source.gs/dead-by-daylight/img/s37p02-56090d.webp'),
    ('Scavenger','While repairing and while your Toolbox is empty, whenever you hit a great basic Skill Check, you earn 1 Token. When you have 5 Tokens, spend them all: - Your Toolbox is recharged instantly. - You repair 50% slower for 40/35/30 s. You can rummage Chests 1 time. The first time you rummage a Chest, it will contain an uncommon Toolbox.','Gabriel Soma','https://cdn.source.gs/dead-by-daylight/img/s37p03-234b28.webp'),
    ('Troubleshooter','While chased by the Killer: - You see the Aura of the Generator with the most progress. - Whenever you drop a Pallet, you see the Killer''s Aura for 4/5/6 s. When the Killer stops chasing you, this ends after 6/8/10 s.','Gabriel Soma','https://cdn.source.gs/dead-by-daylight/img/s37p01-bc8ba0.webp'),
    ('Dramaturgy','While healthy and running, use Active Ability button 1: - You gain 25% Haste for 2 s. - You gain Exhausted for 60/50/40 s. Then, one happens at random: - You gain 25% Haste for 2 s. - You gain Exposed for 12 s. - You gain a random rare item with random add-ons. - You scream, but nothing happens. The same effect cannot happen twice in a row.','Nicolas Cage','https://cdn.source.gs/dead-by-daylight/img/s38p01-2b3e55.webp'),
    ('Plot Twist','While injured, crouched and idle, use Active Ability button 2 to be downed silently. While downed this way, once per trial: - You make no Grunts of Pain. - You leave no Pools of Blood. - You recover 25% faster. - You can fully recover. Whenever you recover this way: - You gain 50% Haste for 2/3/4 s. - You are healed instantly. When all Generators are completed, you can use this ability once again.','Nicolas Cage','https://cdn.source.gs/dead-by-daylight/img/s38p03-69f52b.webp'),
    ('Scene Partner','While you are within the Killer''s Terror Radius, whenever you look at them: - Scream, then see the Killer''s Aura for 4/5/6 s. - There is a 50% chance you will scream again. If you do, you see the Killer''s Aura for 2 s more. Cooldown: 40 s.','Nicolas Cage','https://cdn.source.gs/dead-by-daylight/img/s38p02-c35011.webp'),
    ('Chemical Trap','After repairing 20% of Generators, while next to a Dropped Pallet, use Active Ability button 2 to trap it for 40/50/60 s. All Survivors see that Pallet''s Aura for that time. When the Killer breaks that Pallet, the trap explodes and they gain 50% Hindered for 4 s.','Ellen Ripley','https://cdn.source.gs/dead-by-daylight/img/s39p02-593f36.webp'),
    ('Light-footed','While healthy and running, your footsteps are silent to the Killer. Whenever you do a fast-action, cooldown: 14/12/10 s.','Ellen Ripley','https://cdn.source.gs/dead-by-daylight/img/s39p03-1008b5.webp'),
    ('Lucky Star','While hiding in a Locker, you make no Grunts of Pain. Whenever you exit a Locker, for 30 s: - You see the Aura of the closest Generator. - You see the Auras of other Survivors. - You make no Grunts of Pain. - You leave no Pools of Blood. Cooldown: 35/30/25 s.','Ellen Ripley','https://cdn.source.gs/dead-by-daylight/img/s39p01-f47945.webp'),
    ('Boon: Illumination','While next to a Totem, use Active Ability button 1 to bless it, creating a unique Boon Totem that combines all your Boons. Survivors within the Boon''s range: - See the Auras of Chests. - See the Auras of Generators. While you have a Boon Totem, you bless 150/175/200% faster.','Alan Wake','https://cdn.source.gs/dead-by-daylight/img/s40p02-24a122.webp'),
    ('Champion of Light','While you are using a Flashlight, you gain 50% Haste. Whenever you blind the Killer, they gain 20% Hindered for 6 s. Cooldown: 60/50/40 s.','Alan Wake','https://cdn.source.gs/dead-by-daylight/img/s40p01-c38ded.webp'),
    ('Deadline','While injured, basic Skill Checks: - Are 6/8/10% more likely to appear. - Appear in random places. Whenever you miss a basic Skill Check, you lose 50% less progress.','Alan Wake','https://cdn.source.gs/dead-by-daylight/img/s40p03-12aa78.webp'),
    ('Invocation: Weaving Spiders','While in the Basement next to the circle, use Active Ability button 1 to invoke. While invoking, other Survivors see your Aura and can join your Invocation. When the Invocation is completed: - All Generators gain 8/9/10 permanent charges. - You become injured. - You gain Broken. Each Invocation can only be completed once per trial.','Sable Ward','https://cdn.source.gs/dead-by-daylight/img/s41p01-c98b60.webp'),
    ('Strength in Shadows','While in the Basement: - You can heal yourself, but 30% slower. - Whenever you finish healing, you see the Killer''s Aura for 6/8/10 s.','Sable Ward','https://cdn.source.gs/dead-by-daylight/img/s41p02-bac5bf.webp'),
    ('Wicked','While in the Basement, you can unhook yourself. Whenever you are unhooked, you see the Killer''s Aura for 16/18/20 s.','Sable Ward','https://cdn.source.gs/dead-by-daylight/img/s41p03-a6680b.webp'),
    ('Bardic Inspiration','While idle, use Active Ability button 1 to perform, empowering all Survivors within 16 m for up to 15 s. While you are performing, other Survivors will see your Aura. Roll a d20: - 1 | You scream, but nothing happens. - 2-10 | Basic Skill Checks give + 1% progress. - 11-19 | Basic Skill Checks give + 2% progress. - 20 | Basic Skill Checks give + 3% progress. If you complete the performance, this effect ends after 90 s. Cooldown: 110/100/90 s.','Aestri Yazar','https://cdn.source.gs/dead-by-daylight/img/s42p02-b46207.webp'),
    ('Mirrored Illusion','After repairing 20% of Generators, while next to a Chest, Exit Gate Switch, Generator, or Totem, use Active Ability button 2 to create a static illusion for 40/50/60 s.','Aestri Yazar','https://cdn.source.gs/dead-by-daylight/img/s42p01-bebcdf.webp'),
    ('Still Sight','After being idle for 4/3/2 s, within 24 m, until you start moving: - You see the Killer''s Aura. - You see the Auras of Chests. - You see the Auras of Generators.','Aestri Yazar','https://cdn.source.gs/dead-by-daylight/img/s42p03-2ee1a6.webp'),
    ('Finesse','While healthy, you fast-vault 20% faster. Whenever you fast-vault, cooldown: 40/35/30 s.','Lara Croft','https://cdn.source.gs/dead-by-daylight/img/s43p01-4d1e0e.webp'),
    ('Hardened','When you have blessed or cleansed a Totem and unlocked a Chest, whenever you would scream, you see the Killer''s Aura for 3/4/5 s instead.','Lara Croft','https://cdn.source.gs/dead-by-daylight/img/s43p02-75f8e9.webp'),
    ('Specialist','Whenever you rummage or unlock a Chest, you earn 1 Token, up to 6. While repairing a Generator, whenever you hit a great basic Skill Check, spend all Tokens. For each Token spent, the Generator gains 2/3/4% permanent progress.','Lara Croft','https://cdn.source.gs/dead-by-daylight/img/s43p03-a755b9.webp'),
    ('Exultation','Whenever you Pallet-stun the Killer: - Your item rarity is upgraded to the next tier, if possible. - If the item was upgraded, it recharges 75% Charges. Cooldown: 30/25/20 s.','Trevor Belmont','https://cdn.source.gs/dead-by-daylight/img/s44p02-c7bcb8.webp'),
    ('Eyes of Belmont','Whenever a Generator is completed, you see the Killer''s Aura for 1/2/3 s. Whenever you see the Killer''s Aura for a duration, it is 2 s longer.','Trevor Belmont','https://cdn.source.gs/dead-by-daylight/img/s44p01-b0ff1d.webp'),
    ('Moment of Glory','After you rummage or unlock 1 Chest, while not Broken, when you become injured, gain Broken. After 80/70/60 s, if you are not downed, you are instantly healed.','Trevor Belmont','https://cdn.source.gs/dead-by-daylight/img/s44p03-cc3ebe.webp'),
    ('Clean Break','Whenever you finish healing another Survivor, while being healed by another Survivor, use Active Ability button 1 to gain Broken. After 75/60/45 s, if you are not downed, you are instantly healed.','Taurie Cain','https://cdn.source.gs/dead-by-daylight/img/s45p02-f636c7.webp'),
    ('Invocation: Treacherous Crows','While in the Basement next to the circle, use Active Ability button 2 to invoke. While invoking, other Survivors see your Aura and can join your Invocation. When the Invocation is completed: - Whenever the Killer scares a Crow while a Survivor is in their Terror Radius, all Survivors see the Killer''s Aura for 1/1.5/2 s. - You become injured. - You gain Broken. Each Invocation can only be completed once per trial.','Taurie Cain','https://cdn.source.gs/dead-by-daylight/img/s45p01-c34cd9.webp'),
    ('Shoulder the Burden','Once per trial, if you have less than 2 Hook States while you are next to a hooked Survivor, use Active Ability button 2 to unhook them: - They lose 1 Hook State. - You gain 1 Hook State. - You scream. - You become Injured. - You gain Broken for 160/140/120 s.','Taurie Cain','https://cdn.source.gs/dead-by-daylight/img/s45p03-619f05.webp'),
    ('Do No Harm','While healing another Survivor, for each Hook State they have: - You heal 30/35/40% faster. - Great basic Skill Checks grant 3% more progress. - Basic Skill Checks are 5% more likely to appear.','Orela Rose','https://cdn.source.gs/dead-by-daylight/img/s46p01-7e94c4.webp'),
    ('Duty of Care','While healthy, whenever you take a protection hit, other Survivors within 12 m gain 25% Haste for 4/5/6 s.','Orela Rose','https://cdn.source.gs/dead-by-daylight/img/s46p02-482ac1.webp'),
    ('Rapid Response','Whenever you fast-exit a Locker, you gain Exhausted for 30/25/20 s. Whenever you gain Exhausted, you see the Killer''s Aura for 2 s.','Orela Rose','https://cdn.source.gs/dead-by-daylight/img/s46p03-45a7be.webp'),
    ('Apocalyptic Ingenuity','After you rummage or unlock 1 Chest, while next to a Broken Pallet, use Active Ability button 1 for 3 s to create a Fragile Pallet. Within 24/28/32 m, you see the Auras of Broken Pallets.','Rick Grimes','https://cdn.source.gs/dead-by-daylight/img/s47p01-39a850.webp'),
    ('Come and Get Me!','Whenever you unhook a Survivor, while crouched and idle, use Active Ability button 1 to have injured and downed Survivors within 24 m: - Make no Grunts of Pain for 10/12.5/15 s. - Leave no Pools of Blood for 10/12.5/15 s. - Leave no Scratch Marks for 10/12.5/15 s. You scream, then the Killer sees your Aura for 5 s.','Rick Grimes','https://cdn.source.gs/dead-by-daylight/img/s47p02-8ff9cc.webp'),
    ('Teamwork: Toughen Up','While injured, whenever another Survivor within 24 m of you blinds or Pallet-stuns the Killer, for 20/25/30 s: - You make no Grunts of Pain. - You leave no Pools of Blood. - You leave no Scratch Marks.','Rick Grimes','https://cdn.source.gs/dead-by-daylight/img/s47p03-f26c18.webp'),
    ('Conviction','After you finish healing 1 other Survivor, while downed with at least 25% recovery, use Active Ability button 1 to recover instantly. You gain Broken, then, after 20/25/30 s, you are downed instantly.','Michonne','https://cdn.source.gs/dead-by-daylight/img/s48p01-016aeb.webp'),
    ('Last Stand','After hiding for 120/105/90 s within the Killer''s Terror Radius, when you fast-vault, once per trial, stun the Killer for 3 s if they are within 2.5 m.','Michonne','https://cdn.source.gs/dead-by-daylight/img/s48p02-5d3dc4.webp'),
    ('Teamwork: Throw Down','Whenever you blind or Pallet-stun the Killer, for 6/8/10 s, other injured Survivors within 24 m: - Gain Endurance. - See the Killer''s Aura.','Michonne','https://cdn.source.gs/dead-by-daylight/img/s48p03-7a1eaa.webp'),
    ('Ghost Notes','While you have Exhausted, your Scratch Marks disappear 50% faster. You lose Exhausted 5/7.5/10% faster.','Vee Boonyasak','https://cdn.source.gs/dead-by-daylight/img/s49p03-8f948f.webp'),
    ('ONE-TWO-THREE-FOUR!','While idle, use Active Ability button 2 to perform, empowering all Survivors within 16 m for up to 15 s. While you are performing, other Survivors will see your Aura. You get special Skill Checks during that time: while healing or repairing, basic Skill Checks are 20% more likely to appear. If you complete the performance, the effect ends after 90 s. Cooldown: 110/100/90 s.','Vee Boonyasak','https://cdn.source.gs/dead-by-daylight/img/s49p02-741b49.webp'),
    ('Road Life','While injured and repairing a Generator: - Whenever you hit a great basic Skill Check, you earn 1 Token. - Whenever you miss a basic Skill Check, you lose 1 token. When you have 6/5/4 Tokens, you can heal yourself. Spend all Tokens to heal yourself 10% faster. When you stop healing, this ends after 4 s.','Vee Boonyasak','https://cdn.source.gs/dead-by-daylight/img/s49p01-6c1bd1.webp'),
    ('Bada Bada Boom','After repairing 20% of Generators, while next to a Window, use Active Ability button 2 to trap it for 40/50/60 s. All Survivors see that Window''s Aura for that time. When the Killer vaults that Window, the trap explodes and they gain 50% Hindered for 4 s.','Dustin Henderson','https://cdn.source.gs/dead-by-daylight/img/s50p01-404207.webp'),
    ('Change of Plan','When the trial starts, you earn 2 Tokens. While hiding in a Locker and holding a non-event Toolbox, use Active Ability button 2 and spend 1 Token to transform your Toolbox and add-ons into a Med-Kit of the same rarity with 80/90/100% Charges and random add-ons of the same rarity.','Dustin Henderson','https://cdn.source.gs/dead-by-daylight/img/s50p02-c4936b.webp'),
    ('Teamwork: Full Circuit','For each other Survivor repairing a Generator with you, good basic Skill Check zones are 15/20/25% bigger. While repairing with at least 1 other Survivor, you repair 5% faster.','Dustin Henderson','https://cdn.source.gs/dead-by-daylight/img/s50p03-bffdee.webp'),
    ('Extrasensory Perception','After crouching for 4 s: - You see Auras in an expanding radius up to 44 m. - You gain Elusive. - You gain Oblivious. When you stop crouching, or after 11 s, cooldown: 60/50/40 s.','Eleven','https://cdn.source.gs/dead-by-daylight/img/s51p01-dd97ce.webp'),
    ('Teamwork: Soft-Spoken','For each other Survivor repairing a Generator with you, the range of Generator repair noises is 15/20/25% smaller. While repairing with at least 1 other Survivor, you repair 5% faster.','Eleven','https://cdn.source.gs/dead-by-daylight/img/s51p03-a449a6.webp'),
    ('We See You','Whenever the Killer sees your Aura, you earn 1 Token. Cooldown: 10 s. When you have 4 Tokens, spend them all. Then, all Survivors see the Killer''s Aura for 10/12.5/15 s.','Eleven','https://cdn.source.gs/dead-by-daylight/img/s51p02-932df6.webp'),
    ('A Place For Us','While healing another Survivor, you both gain Elusive. Whenever you finish healing the Obsession, you both gain Elusive for 20/25/30 s. When the trial starts, you are less likely to be the Obsession.','Kwon Tae-Young','https://cdn.source.gs/dead-by-daylight/img/s52p02-8c1481.webp'),
    ('Five Moves Ahead','While you are in the Killer''s Terror Radius or chased by the Killer: - You see the Auras of the 5 closest Pallets. - After you drop a Pallet, you start moving 50% earlier. - Whenever you drop a Pallet, cooldown: 40/35/30 s.','Kwon Tae-Young','https://cdn.source.gs/dead-by-daylight/img/s52p03-cbbbb4.webp'),
    ('Flow State','Whenever a Generator is completed, earn 1 Token, up to 5. For each Token: - You bless and cleanse Totems 13/14/15% faster. - You heal 13/14/15% faster. - You unhook Survivors 13/14/15% faster.','Kwon Tae-Young','https://cdn.source.gs/dead-by-daylight/img/s52p01-214972.webp'),
    ('Cross-Examination','While in the Killer''s Terror Radius and not being chased by the Killer, they leave Light Marks that last for 10 s that you can see. While on the Killer''s Light Marks, you gain Elusive. This ends after 3/4/5 s.','Shane Wiigwaas','https://cdn.source.gs/dead-by-daylight/img/s53p03-7487ea.webp'),
    ('Lend a Hand','Whenever you bless or cleanse 1 Totem, while healing another Survivor and only once per Survivor, use Active Ability button 2 to give them 2/3/4 permanent healing charges.','Shane Wiigwaas','https://cdn.source.gs/dead-by-daylight/img/s53p02-062c8a.webp'),
    ('Wide Open Throttle','Whenever you fast-vault a Pallet: - You gain 10/12.5/15% Haste for 3 s. - The Pallet is reset, blocked for 60 s, and all Survivors see its Aura for that time. Cooldown: 60 s.','Shane Wiigwaas','https://cdn.source.gs/dead-by-daylight/img/s53p01-0e5d26.webp'),
    ('Boon: Steadfast','While next to a Totem, use Active Ability button 1 to bless it, creating a unique Boon Totem that combines all your Boons. Generators within the Boon''s range: - Regress 50% slower. - Survivors repair them 8/9/10% faster. Survivors within the Boon''s range see the Auras of affected Generators.','Aurora Stardotter','https://cdn.source.gs/dead-by-daylight/img/s54p03-16817c.webp'),
    ('Fruits of Your Labor','Whenever a Generator is completed, you earn 1 Token. Whenever you finish repairing a Generator, for each Token: - You gain 5% Haste for 2 s. - You gain 10/15/20% healing progress.','Aurora Stardotter','https://cdn.source.gs/dead-by-daylight/img/s54p01-d8bd76.webp'),
    ('Salvation''s Cry','Whenever the Killer starts chasing you: - You see the Auras of other Survivors for 1/2/3 s. - Survivors not being chased see your Aura for 5 s. - Survivors not being chased see the Killer''s Aura for 5 s.','Aurora Stardotter','https://cdn.source.gs/dead-by-daylight/img/s54p02-4311ac.webp')
) AS p(nombre,descripcion,owner,imagen)
JOIN public."Survivors" s ON s."Nombre" = p.owner;

COMMIT;

SELECT 'Perks Killer' AS grupo, count(*) AS total FROM public."Perks" WHERE "TipoPersonaje" = 'Killer'
UNION ALL SELECT 'Perks Survivor', count(*) FROM public."Perks" WHERE "TipoPersonaje" = 'Survivor'
UNION ALL SELECT 'Killers sin perks', count(*) FROM public."Killers" k WHERE NOT EXISTS (SELECT 1 FROM public."Perks" p WHERE p."KillerId" = k."Id")
UNION ALL SELECT 'Survivors sin perks', count(*) FROM public."Survivors" s WHERE NOT EXISTS (SELECT 1 FROM public."Perks" p WHERE p."SurvivorId" = s."Id");
